import {describe,it,expect,vi} from 'vitest'
import {DanceRun,validateDanceSet} from './dance'
const tracks:any[]=[{id:'a',duration:150,windows:[{end:8}]},{id:'b',duration:150,windows:[{end:8}]},{id:'c',duration:150,windows:[{end:8}]}]
function fixture(){const run=new DanceRun({id:'set',style:'Hip-Hop',seconds:300,tracks});const p:any={current:tracks[0],ctx:{currentTime:0,suspend:vi.fn(async()=>{})},playing:true,position:0,pending:null,busy:false,tracks,log:vi.fn(),request:vi.fn(async()=>{}),cancel:vi.fn(),setVolume:vi.fn(),stop:vi.fn()};return {run,p}}
describe('automatic dance session',()=>{
 it('starts planning the next selected song without a tap',()=>{const {run,p}=fixture();run.tick(p);p.ctx.currentTime=100;p.position=100;run.tick(p);expect(p.request).toHaveBeenCalledWith({kind:'next',targetId:'b'},30,{origin:'dance_auto'});expect(run.snapshot().index).toBe(0)})
 it('keeps audio-clock time when paused and removes completed songs from candidate pool',()=>{const {run,p}=fixture();run.tick(p);p.ctx.currentTime=40;run.tick(p);p.playing=false;run.tick(p);run.tick(p);expect(run.elapsed).toBe(40);p.playing=true;p.current=tracks[1];p.ctx.currentTime=90;run.tick(p);expect(p.tracks.map((t:any)=>t.id)).toEqual(['b','c']);expect(run.index).toBe(1)})
 it('cancellation postpones automatic retries and a locked plan is left alone',()=>{const {run,p}=fixture();run.tick(p);p.ctx.currentTime=80;run.postpone(p);run.tick(p);expect(p.request).not.toHaveBeenCalled();p.ctx.currentTime=100;p.pending={};run.tick(p);expect(p.request).not.toHaveBeenCalled()})
 it('fades and ends against session time, not source seek position',()=>{const {run,p}=fixture();run.tick(p);p.ctx.currentTime=298;p.position=20;run.tick(p);expect(run.finished).toBe(false);p.ctx.currentTime=299;run.tick(p);expect(p.setVolume).toHaveBeenCalledWith(.85/3);p.ctx.currentTime=300;run.tick(p);expect(p.stop).toHaveBeenCalled();expect(run.finished).toBe(true);expect(p.ctx.suspend).toHaveBeenCalled()})
 it('stopping cannot restart automatically',()=>{const {run,p}=fixture();run.tick(p);run.stop();p.ctx.currentTime=120;run.tick(p);expect(p.request).not.toHaveBeenCalled()})
 it('rejects arbitrary URLs and invalid durations before configuring the engine',()=>{expect(()=>validateDanceSet({schema:'harbeat.dance_set.v1',seconds:Infinity,tracks})).toThrow();const t:any={id:'track-'+'a'.repeat(20),duration:150,windows:[],bars:[],energy:[],vocals:[],native:{url:'https://evil.invalid/a.flac'}};expect(()=>validateDanceSet({schema:'harbeat.dance_set.v1',seconds:300,tracks:[t,{...t,id:'track-'+'b'.repeat(20)}]})).toThrow()})
})
